
INSERT INTO public.partner_assets
(title, description, category, asset_type, product, language, industry, is_cobrandable, status, version_label, certification_min, is_active, sort_order, content)
VALUES
(
 'WorldAML Social Media Kit — Partner Edition',
 'Ready-to-post LinkedIn and X copy, image direction and hashtags for promoting WorldAML as a partner.',
 'social', 'Copy pack + image direction', 'WorldAML Platform', 'English', 'All industries', true, 'draft', 'v1.0', 'bronze', true, 20,
 '{"kind":"social_kit","summary":"A 30-day social pack: 8 LinkedIn posts, 4 short-form posts and image direction. Replace placeholders before posting; do not alter product claims.","placeholders":["{{PARTNER_NAME}}","{{PARTNER_URL}}","{{CONTACT_EMAIL}}"],"items":[{"type":"LinkedIn","title":"Post 1 — Partnership announcement","body":"{{PARTNER_NAME}} is now an official WorldAML partner. Together we help regulated firms onboard customers faster, screen against 1,900+ global watchlists and evidence every decision for their regulator.\n\nTalk to us: {{CONTACT_EMAIL}}","hashtags":["#AML","#KYC","#Compliance","#RegTech"],"cta":"Book a 20-minute walkthrough","landing_page":"https://worldaml.com/contact-sales"},{"type":"LinkedIn","title":"Post 2 — Problem / insight","body":"Most compliance teams do not have a screening problem. They have an evidence problem. When the regulator asks why a customer was cleared in 2023, can you show the list version, the match score and the reviewer?\n\nWorldAML records all three, automatically.","hashtags":["#AMLCompliance","#Sanctions","#Audit"],"cta":"See how audit trails work"},{"type":"LinkedIn","title":"Post 3 — Sanctions screening","body":"Sanctions lists change weekly. Your customer book does not re-screen itself.\n\nWorldAML runs continuous screening across 1,900+ global lists — PEPs, sanctions, adverse media and enforcement — and raises an alert only when something material changes.","hashtags":["#Sanctions","#PEP","#AML"],"cta":"Request a screening demo"},{"type":"LinkedIn","title":"Post 4 — KYC / KYB onboarding","body":"Onboarding a corporate customer should not take three weeks of email attachments.\n\nWith WorldAML: a branded onboarding form, document capture, UBO mapping and automatic screening — with a decision file the regulator can read.","hashtags":["#KYB","#KYC","#Onboarding"],"cta":"See the onboarding flow"},{"type":"LinkedIn","title":"Post 5 — Risk-based approach","body":"A risk-based approach only works if the risk score is explainable.\n\nWorldAML scores each customer across jurisdiction, product, channel, behaviour and screening outcome — and shows exactly which factor moved the score.","hashtags":["#RiskManagement","#AML"],"cta":"Ask for the risk model overview"},{"type":"LinkedIn","title":"Post 6 — Academy / people","body":"Technology does not sit the regulator interview — your MLRO does.\n\nWorldAML Academy delivers CPD-aligned AML training with certificates your team can evidence. {{PARTNER_NAME}} clients get access as part of onboarding.","hashtags":["#AMLTraining","#CPD","#MLRO"],"cta":"Explore WorldAML Academy","landing_page":"https://academy.worldaml.com"},{"type":"LinkedIn","title":"Post 7 — Customer proof / use case","body":"A payments firm replaced four spreadsheets, one shared inbox and a manual list check with a single compliance workspace. Periodic reviews now schedule themselves.\n\nThat is the WorldAML Suite.","hashtags":["#Fintech","#Payments","#Compliance"],"cta":"Book a walkthrough"},{"type":"LinkedIn","title":"Post 8 — Direct offer","body":"Reviewing your AML tooling this quarter? {{PARTNER_NAME}} runs a free 30-minute compliance gap review using the WorldAML framework — onboarding, screening, monitoring, reporting, training.\n\nBook here: {{PARTNER_URL}}","hashtags":["#AML","#Compliance"],"cta":"Book a gap review","landing_page":"{{PARTNER_URL}}"},{"type":"Short-form (X / Threads)","title":"Short posts","bullets":["Sanctions lists change weekly. Your customer book does not re-screen itself. WorldAML does.","KYB without UBO mapping is not KYB.","If you cannot show the reviewer, the list version and the score, you do not have an audit trail.","Compliance made smarter — onboarding, screening, monitoring, reporting in one place."]},{"type":"Image direction","title":"Visual guidance","bullets":["Deep navy background with teal accent line; never place the logo on busy photography.","Use one statistic per image, maximum 8 words of overlay text.","Partner logo bottom-left, WorldAML logo bottom-right, equal optical weight.","Export 1200x627 for LinkedIn link posts, 1080x1080 for square."]}],"governance":"Do not modify product claims, coverage figures or regulatory statements. Co-branded versions must be requested through the portal before external use."}'::jsonb
),
(
 'WorldAML Email Nurture Sequence — 5 Emails',
 'A five-email sequence to take a cold compliance contact from awareness to a booked demo.',
 'email_campaign', 'Email sequence', 'WorldAML Compliance Suite', 'English', 'All industries', true, 'draft', 'v1.0', 'bronze', true, 21,
 '{"kind":"email_sequence","summary":"Five emails over 21 days aimed at MLROs, Heads of Compliance and COOs at regulated firms. Send from a named person, not a generic mailbox.","placeholders":["{{FIRST_NAME}}","{{COMPANY}}","{{PARTNER_NAME}}","{{SENDER_NAME}}","{{MEETING_LINK}}"],"items":[{"type":"Day 0","title":"Email 1 — The evidence question","subject":"Quick question about {{COMPANY}}''s AML evidence trail","preheader":"Can you reproduce a 2023 onboarding decision in under five minutes?","body":"Hi {{FIRST_NAME}},\n\nOne question we ask every compliance team: if your regulator asked why a customer was cleared eighteen months ago, how long would it take to produce the list version, the match score and the reviewer name?\n\nFor most teams it is hours of digging. WorldAML records it automatically at the moment of the decision.\n\nWorth a 20-minute look?\n\n{{SENDER_NAME}}, {{PARTNER_NAME}}","cta":"Book 20 minutes","url":"{{MEETING_LINK}}"},{"type":"Day 4","title":"Email 2 — Screening coverage","subject":"1,900+ lists, screened continuously","preheader":"Not a weekly batch job","body":"Hi {{FIRST_NAME}},\n\nMost firms screen at onboarding and then re-screen periodically. The gap between those two events is where the exposure lives.\n\nWorldAML screens continuously across 1,900+ global sanctions, PEP, adverse media and enforcement lists, and only raises an alert when a match materially changes.\n\nHappy to show you the alert queue on a live tenant.\n\n{{SENDER_NAME}}","cta":"See the alert queue"},{"type":"Day 9","title":"Email 3 — Onboarding and UBO","subject":"KYB in days, not weeks","body":"Hi {{FIRST_NAME}},\n\nCorporate onboarding tends to fail on two things: chasing documents and mapping ownership.\n\nWorldAML gives you a branded onboarding form, structured document capture with expiry tracking, and a UBO tree with percentage holdings — screened as it is built.\n\nWould a walkthrough with your onboarding team be useful?\n\n{{SENDER_NAME}}","cta":"Walk through onboarding"},{"type":"Day 14","title":"Email 4 — Reporting and reviews","subject":"Periodic reviews that schedule themselves","body":"Hi {{FIRST_NAME}},\n\nRisk-rated review cadences, overdue flags, document expiry sweeps and regulator-ready report exports — all handled inside the same workspace as your screening and case work.\n\nThat is usually where teams see the time back.\n\n{{SENDER_NAME}}","cta":"See a sample report pack"},{"type":"Day 21","title":"Email 5 — Break-up / gap review","subject":"Closing the loop, {{FIRST_NAME}}","body":"Hi {{FIRST_NAME}},\n\nI will stop here. If timing is wrong, that is fine.\n\nIf it would help, {{PARTNER_NAME}} runs a free 30-minute compliance gap review across onboarding, screening, monitoring, reporting and training — no obligation and you keep the notes.\n\n{{SENDER_NAME}}","cta":"Book the gap review","url":"{{MEETING_LINK}}"},{"type":"Guidance","title":"Sending rules","bullets":["Comply with GDPR / ePrivacy: legitimate interest basis, working addresses only, one-click unsubscribe in every send.","Never state or imply that WorldAML guarantees regulatory approval.","Keep sequences under 200 contacts per day per sending domain to protect deliverability."]}],"governance":"Copy may be personalised, but product capability statements must remain unchanged."}'::jsonb
),
(
 'WorldAML API & Integrations — Partner One-Pager',
 'Technical sales sheet covering the screening and KYC/KYB APIs, authentication, latency and integration patterns.',
 'one_pager', 'Technical one-pager', 'WorldAML API', 'English', 'All industries', true, 'draft', 'v1.0', 'bronze', true, 22,
 '{"kind":"one_pager","summary":"For technical buyers and solution architects evaluating WorldAML as an embedded compliance layer.","pages_target":"1 page (A4, double-sided optional)","sections":[{"heading":"The problem","body":"Compliance checks live outside the product. Engineering teams end up wiring three vendors together, each with its own auth model, data shape and retry behaviour."},{"heading":"The WorldAML approach","body":"One REST API for screening, KYC/KYB and monitoring, with a shared customer record and a single audit trail behind it."},{"heading":"Core endpoints","bullets":["Screening — submit a name, entity or batch and receive scored matches with list provenance.","KYC / KYB — create onboarding sessions, upload documents, retrieve verification outcomes.","Customers — create and update the customer record that risk scoring and monitoring run on.","Cases & alerts — pull open alerts, post decisions, close cases with reasons.","Reports — export regulator-ready filings and periodic review packs."]},{"heading":"Integration essentials","bullets":["Authentication: API key per environment; sandbox keys issued automatically to partners.","Idempotency keys on all write operations.","Webhooks for alert raised, screening match, document expiry and case status change.","Structured error codes with retry guidance; no silent failures.","Sandbox tenant with seeded data for build and demo work."]},{"heading":"Why partners lead with it","bullets":["Embed compliance inside the client''s existing product rather than adding another portal.","Implementation revenue on top of referral or reseller commission.","One vendor relationship for screening, onboarding and monitoring."]},{"heading":"Talk track","body":"Ask the prospect: where does compliance data live today, and how many systems must agree before a customer is approved? If the answer is more than one, the API is the shortest path to fixing it."}],"governance":"Do not publish endpoint schemas or credentials in client-facing materials. Direct technical questions to your partner manager."}'::jsonb
),
(
 'Banking & Fintech — Industry Campaign Kit',
 'Positioning, objection handling and outbound copy for banks, EMIs and payment institutions.',
 'campaign_kit', 'Industry kit', 'WorldAML Compliance Suite', 'English', 'Fintech / EMI', true, 'draft', 'v1.0', 'bronze', true, 23,
 '{"kind":"industry_kit","summary":"Everything needed to run a focused campaign into banks, EMIs and payment institutions.","placeholders":["{{PARTNER_NAME}}","{{MEETING_LINK}}"],"items":[{"type":"Positioning","title":"How to frame WorldAML","body":"Banks and EMIs are not short of controls — they are short of connected controls. WorldAML joins onboarding, screening, transaction monitoring and reporting into one evidenced workflow, so supervisory reviews stop being archaeology projects."},{"type":"Pain points","title":"What these buyers actually feel","bullets":["Alert volume from legacy rules with no tuning or backtesting capability.","Onboarding SLAs slipping on corporate customers and UBO chains.","Manual periodic reviews tracked in spreadsheets.","Regulator requests requiring days of manual evidence assembly.","Fragmented data between core banking, screening vendor and case tooling."]},{"type":"Discovery questions","title":"Ask these first","bullets":["How many alerts does your team close per analyst per day, and what proportion are false positives?","When you change a monitoring rule, can you backtest it before it goes live?","Who owns periodic reviews, and how are overdue reviews escalated?","How long does a regulator information request take to fulfil today?"]},{"type":"Objection handling","title":"Common pushback","bullets":["\"We already have a screening vendor.\" — Good. WorldAML often sits above it as the case, evidence and reporting layer, or replaces it if coverage is the issue.","\"Procurement will take a year.\" — Start with a scoped pilot on one product line; the tenant is provisioned in days.","\"Our core system cannot integrate.\" — The API is REST with webhooks; most integrations start read-only."]},{"type":"Outbound email","title":"Cold email","subject":"Alert tuning without the guesswork","body":"Hi there — most monitoring teams change rules and hope. WorldAML lets you backtest a rule against historical transactions before it goes live, so you know the alert volume in advance. Worth 20 minutes?","cta":"Book a session","url":"{{MEETING_LINK}}"},{"type":"LinkedIn","title":"Social post","body":"Changing an AML monitoring rule without backtesting it is a controlled experiment on your own analysts. WorldAML shows the alert volume before the rule goes live.","hashtags":["#Banking","#Fintech","#AML","#TransactionMonitoring"]}],"governance":"Regulatory references must not be presented as legal advice. Adapt to the client''s supervisor before sending."}'::jsonb
),
(
 'Gaming & iGaming — Industry Campaign Kit',
 'Campaign assets for MGA, UKGC and other licensed gaming operators.',
 'campaign_kit', 'Industry kit', 'WorldAML Compliance Suite', 'English', 'Gaming / iGaming', true, 'draft', 'v1.0', 'bronze', true, 24,
 '{"kind":"industry_kit","summary":"Targets AML and responsible gaming leads at licensed operators, where source of funds and player monitoring drive the buying decision.","placeholders":["{{PARTNER_NAME}}","{{MEETING_LINK}}"],"items":[{"type":"Positioning","title":"How to frame WorldAML","body":"Licensed operators are judged on whether they can evidence source of funds decisions and detect player-level abuse. WorldAML brings player onboarding, SoF documentation, screening and behavioural monitoring into one supervised record."},{"type":"Pain points","title":"What these buyers actually feel","bullets":["Source of funds evidence scattered across email and shared drives.","Threshold-driven interventions applied inconsistently between shifts.","Chip dumping, bonus abuse and account layering detected late or not at all.","Licence condition reporting assembled manually each cycle."]},{"type":"Discovery questions","title":"Ask these first","bullets":["At what deposit threshold do you request source of funds, and how is that decision recorded?","How do you evidence that a player intervention actually happened?","Can you show linked-account behaviour across players, not just per account?","What does your regulator ask for that takes longest to produce?"]},{"type":"Objection handling","title":"Common pushback","bullets":["\"Our platform provider handles AML.\" — Platform providers handle transactions; supervisors ask for compliance evidence. Those are different artefacts.","\"We are a small operator.\" — Licence conditions do not scale down. Start with SoF and screening only."]},{"type":"Outbound email","title":"Cold email","subject":"Source of funds evidence, in one place","body":"Hi there — when your regulator asks how a high-value player was cleared, the answer usually lives in an inbox. WorldAML captures SoF declarations, documents, thresholds and reviewer decisions as a single record. 20 minutes to show you?","cta":"Book a session","url":"{{MEETING_LINK}}"},{"type":"LinkedIn","title":"Social post","body":"Source of funds is not a document request. It is a decision — and decisions need a reviewer, a threshold and a date. WorldAML records all three.","hashtags":["#iGaming","#AML","#ResponsibleGambling","#Compliance"]}],"governance":"Do not reference specific regulator enforcement cases without approval from WorldAML."}'::jsonb
),
(
 'Crypto & VASP — Industry Campaign Kit',
 'Campaign assets for exchanges, custodians and virtual asset service providers.',
 'campaign_kit', 'Industry kit', 'WorldAML Compliance Suite', 'English', 'Crypto / VASP', true, 'draft', 'v1.0', 'bronze', true, 25,
 '{"kind":"industry_kit","summary":"Targets compliance leads at VASPs facing licensing, Travel Rule and continuous screening obligations.","placeholders":["{{PARTNER_NAME}}","{{MEETING_LINK}}"],"items":[{"type":"Positioning","title":"How to frame WorldAML","body":"VASPs are held to the same AML standard as banks with a fraction of the tooling maturity. WorldAML gives them a supervisable compliance record — onboarding, screening, monitoring and reporting — without building it in-house."},{"type":"Pain points","title":"What these buyers actually feel","bullets":["Licence applications requiring documented policies and evidence of controls.","Travel Rule counterparty obligations layered on top of existing KYC.","Sanctions exposure that changes faster than periodic re-screening cycles.","Investor and banking partners demanding proof of compliance maturity."]},{"type":"Discovery questions","title":"Ask these first","bullets":["Which licences are you applying for or maintaining in the next twelve months?","How do you evidence continuous sanctions screening between reviews?","Who signs off enhanced due diligence, and where is that sign-off stored?","What does your banking partner ask for in their annual review?"]},{"type":"Objection handling","title":"Common pushback","bullets":["\"We use blockchain analytics already.\" — That covers wallets. WorldAML covers the customer, the documents and the decision record.","\"We will build it internally.\" — Build cost is not the issue; supervisory evidence and change control are."]},{"type":"Outbound email","title":"Cold email","subject":"Compliance evidence your licence application needs","body":"Hi there — analytics tell you about a wallet. A supervisor asks about a customer: who approved them, on what evidence, screened against which lists, reviewed when. WorldAML records that end to end. Worth a look before your next filing?","cta":"Book a session","url":"{{MEETING_LINK}}"},{"type":"LinkedIn","title":"Social post","body":"Blockchain analytics answers \"where did the funds move?\" Your regulator asks \"who is the customer, and why did you approve them?\" You need both.","hashtags":["#Crypto","#VASP","#AML","#TravelRule"]}],"governance":"Avoid jurisdiction-specific licensing claims. Confirm local requirements with WorldAML before publishing."}'::jsonb
);
